from math import lcm


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive value divisible by at least one coin."""
    # Inclusion-exclusion counts the union of the multiples of all denominations.
    n = len(coins)
    subset_lcms = []
    for mask in range(1, 1 << n):
        value = 1
        bits = 0
        for i, coin in enumerate(coins):
            if mask >> i & 1:
                value = lcm(value, coin)
                bits += 1
        subset_lcms.append((value, 1 if bits & 1 else -1))

    def count_at_most(x: int) -> int:
        total = 0
        for multiple, sign in subset_lcms:
            if multiple <= x:
                total += sign * (x // multiple)
        return total

    lo, hi = 1, min(coins) * k
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo"}
